// Des: Tests for nt-vend-deco: POST shape, results parsing, bad replies
// Flo: build request > canned JSON replies > assert Rsp
// I/O: canned bodies > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const deco = @import("nt-vend-deco.zig");
const Fake = struct { seen: ?base.Http = null, code: u16, body: []const u8, pub fn send(self: *Fake) base.Send { return .{ .ctx2 = self, .call = cal2 }; } fn cal2(ctx2: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, http: base.Http) anyerror!base.Back { const self: *Fake = @ptrCast(@alignCast(ctx2)); self.seen = http; return .{ .code = self.code, .body = try gpaz.dupe(u8, self.body) }; } };
test "plain has no headless, render adds it; Bearer auth and JSON POST" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const one2 = try deco.requBuil(allo, "TOKEN", .{ .urlz = "https://a.com/x", .mode = .plai }); try std.testing.expect(one2.post); try std.testing.expectEqualStrings("Bearer TOKEN", one2.auth); try std.testing.expectEqualStrings("{\"url\":\"https://a.com/x\"}", one2.body); const two2 = try deco.requBuil(allo, "TOKEN", .{ .urlz = "https://a.com/x", .mode = .rend }); try std.testing.expectEqualStrings("{\"url\":\"https://a.com/x\",\"headless\":\"html\"}", two2.body); const thr2 = try deco.requBuil(allo, "TOKEN", .{ .urlz = "https://a.com/x", .mode = .prem }); try std.testing.expectEqualStrings("{\"url\":\"https://a.com/x\",\"proxy_pool\":\"premium\",\"headless\":\"html\"}", thr2.body); }
test "results[0] content and status_code are read, credits charged" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var fakz: Fake = .{ .code = 200, .body = "{\"results\":[{\"content\":\"<html>hi</html>\",\"status_code\":200}]}" }; const res4 = try deco.call(aren.allocator(), std.testing.allocator, std.testing.io, fakz.send(), "TOKEN", .{ .urlz = "https://a.com/", .mode = .rend }); try std.testing.expectEqual(@as(u16, 200), res4.code); try std.testing.expectEqualStrings("<html>hi</html>", res4.body); try std.testing.expectEqual(@as(u32, 2), res4.cred); }
test "a vendor 200 wrapping a target 403 is a block, uncharged" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var fakz: Fake = .{ .code = 200, .body = "{\"results\":[{\"content\":\"denied\",\"status_code\":403}]}" }; const res4 = try deco.call(aren.allocator(), std.testing.allocator, std.testing.io, fakz.send(), "TOKEN", .{ .urlz = "https://a.com/", .mode = .plai }); try std.testing.expectEqual(@as(u16, 403), res4.code); try std.testing.expectEqual(@as(u32, 0), res4.cred); }
test "garbage replies become badresp, never a crash" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const bads = [_][]const u8{ "", "not json", "[]", "{}", "{\"results\":[]}", "{\"results\":[1]}", "{\"results\":[{\"content\":5}]}" }; for (bads) |badz| { var fakz: Fake = .{ .code = 200, .body = badz }; const res4 = try deco.call(aren.allocator(), std.testing.allocator, std.testing.io, fakz.send(), "TOKEN", .{ .urlz = "https://a.com/", .mode = .plai }); try std.testing.expectEqualStrings("badresp", res4.errz); try std.testing.expectEqual(@as(u32, 0), res4.cred); } }
